        'confirm_translation' => 'பதிவுசெய்யப்பட்ட செயலாக்கம் முடிந்தது. தேர்ந்தெடுத்த மொழிபெயர்ப்பு முடிந்ததை உறுதிப்படுத்தி, பெறுதல் அல்லது வழங்கலை ஏற்பாடு செய்யும் முன் இறுதிக் கோப்புகளைப் பதிவேற்றவும்.',
        'release_files' => 'பதிவுசெய்யப்பட்ட செயலாக்கம் முடிந்தது. இறுதிக் கோப்புகளை மதிப்பாய்வு செய்து வழங்கவும். பின்னர் பெறுதல் அல்லது வழங்கலை ஏற்பாடு செய்யவும்.',
        'outstanding_invoices' => 'நிலுவை விலைப்பட்டியல்களை மதிப்பாய்வு செய்து, தேவைப்பட்டால் அனுப்பி, மீதிக் கட்டணத்தைப் பதிவு செய்யவும்.',
        'paid_translation' => 'கட்டணம் பதிவு செய்யப்பட்டது. தேர்ந்தெடுத்த மொழிபெயர்ப்பைத் தொடங்கி, முடிந்த கோப்பை மதிப்பாய்வு செய்து பதிவேற்றவும்.',
        'paid_processing' => 'கட்டணம் பதிவு செய்யப்பட்டது. தேர்ந்தெடுத்த சேவைகளைத் தொடங்கி, கோப்பு நகரும்போது அவற்றின் செயலாக்கப் பதிவுகளைப் புதுப்பிக்கவும்.',
        'paid_other' => 'கட்டணம் பதிவு செய்யப்பட்டது. தேர்ந்தெடுத்த சேவைகளை மதிப்பாய்வு செய்து பணிகளைச் செய்து, தயாரானதும் இறுதி ஆவணங்களைப் பதிவேற்றவும்.',
        'prepare_quote' => 'கோரிக்கையை மதிப்பாய்வு செய்து, சேவைகளை உறுதிப்படுத்தி மதிப்பீட்டைத் தயாரிக்கவும்.',
        'draft_quote' => 'வரைவு மதிப்பீடு தயாராக உள்ளது. மொத்தத் தொகையைச் சரிபார்த்து வாடிக்கையாளருக்கு அனுப்பவும்.',
        'sent_quote' => 'மதிப்பீடு அனுப்பப்பட்டது. வாடிக்கையாளருக்காகக் காத்திருக்கவும் அல்லது செல்லுபடிக் காலம் முடிவடைய நெருங்கினால் தொடர்புகொள்ளவும்.',
        'revise_quote' => 'நிராகரிக்கப்பட்ட அல்லது காலாவதியான மதிப்பீட்டை வாடிக்கையாளருடன் மதிப்பாய்வு செய்து, வேலை தொடர வேண்டுமானால் திருத்தப் பதிப்பைத் தயாரிக்கவும்.',
        'generate_invoice' => 'மதிப்பீடு ஏற்கப்பட்டது. அதன் விலைப்பட்டியலை உருவாக்கி கட்டணத்தை ஏற்பாடு செய்யவும்.',
        'update_actual_stage' => 'அடுத்த உண்மையான படி நடந்ததும் நிலையைப் புதுப்பிக்கவும். உள்ளகக் குறிப்புகள் வாடிக்கையாளருக்குத் தெரியாது.',
        'progress_label' => 'தேர்ந்தெடுத்த சேவைகளுக்கான வழக்கு முன்னேற்றம்',
        'workspace_label' => 'வழக்குப் பகுதிகள்',
        'reason_label' => 'நிலைக் குறிப்பு அல்லது திருத்தக் காரணம்',
        'correction_help' => 'தேர்ந்தெடுத்த சேவைகளின் உண்மையான நிலையைத் தேர்ந்தெடுக்கவும். முந்தைய நிலைக்கு நகர்த்த அல்லது மூடிய வழக்கை மாற்ற காரணமும் கீழுள்ள உறுதிப்படுத்தலும் தேவை.',
        'confirm_correction' => 'இந்த வழக்கை முந்தைய நிலைக்கு நகர்த்த அல்லது மூடிய வழக்கை மாற்ற விரும்புகிறேன்; அதற்கான காரணத்தைப் பதிவு செய்துள்ளேன்.',
        'advance_process' => 'பொருத்தமானபோது வழக்கு நிலையை முன்னேற்று',
        'active_status_required' => 'செயலில் உள்ள வழக்கு நிலையைத் தேர்ந்தெடுக்கவும்.',
        'reversal_required' => 'முந்தைய நிலைக்கு நகர்த்த அல்லது மூடிய வழக்கை மாற்ற காரணமும் வெளிப்படையான உறுதிப்படுத்தலும் தேவை.',
